def solve_game(N):
    # W[n] is True if position n is a winning (N) position for the current player, False if losing (P).
    # We are interested in whether W[1] is False.
    W = [False] * (N + 1)

    # N is the target winning state. The player who reaches N wins.
    # If the game reaches N, the previous player won. This state is technically outside the P/N analysis 
    # for positions < N, but we define the boundary condition: any move to N is a winning move.

    for n in range(N - 1, 0, -1):
        can_win = False

        # Move 1: n + 1
        if n + 1 <= N:
            if n + 1 == N:
                can_win = True # Direct win
            elif not W[n + 1]:
                can_win = True # Move to a losing position

        # Move 2: 2 * n
        if not can_win and 2 * n <= N:
            if 2 * n == N:
                can_win = True # Direct win
            elif not W[2 * n]:
                can_win = True # Move to a losing position

        W[n] = can_win

    # We want Type B, meaning 1 is a losing (P) position.
    return not W[1] # Returns True if Type B (W[1] is False)

